    "author": "“中国天气”微信公号",
    "description": "“中国天气”微信公号10月4日消息，有人国庆放假到第4天，4天都赶上下雨吗？这几天去南方游玩的不少人真的太心酸了，爬个山全是雨雾朦胧，啥景色都瞧不见，几百块的门票+路费就看了个寂寞。 好消息是，接下来好天气就要回来了！ 今天将是整个国庆假期大范围降水的最后阶段。从明天开始到10月上旬末，我国大部地区低层主要受偏北气流控制，降水稀少，晴或多云天气将成为主流，总体利于假期外出及返程。除了海南，因为低空偏东风影响，持续多雨。 干冷北风吹散水汽…",
