    "content": "许镜清。受访者 图 年近84岁的许镜清还在维权。 他是86版电视剧《西游记》作曲者、国家一级作曲家。10月1日，他通过社交媒体账号发布视频表示，自媒体“星火社”未经授权，擅自改编《五百年桑田沧海》并全网传播。他请求各平台、网友不要再使用未经授权改编的作品。 《五百年桑田沧海》是86版《西游记》的经典插曲之一，由阎肃作词、许镜清作曲。“星火社”发布的《五百年沧海桑田》改编自该作品，且发布时未为原词曲作者署名。10月2日，“星火社”发布致歉声明，承认未经授权对原作旋律、歌词大幅改编并公开发布，越过版权边界，相关视频已私…"
