    "author": "",
    "description": "中新网香港10月4日电 (记者 邱兆翔)香港启德医院4日在香港召开发布会，介绍该医院将于5日起分阶段投入使用。作为香港规模最大的公立医院，启德医院将承担起九龙区公营医疗枢纽角色，支援九龙区其他医院联网，进一步加强区内公营医疗服务能力。",
    "content": "中新网香港10月4日电 (记者 邱兆翔)香港启德医院4日在香港召开发布会，介绍该医院将于5日起分阶段投入使用。作为香港规模最大的公立医院，启德医院将承担起九龙区公营医疗枢纽角色，支援九龙区其他医院联网，进一步加强区内公营医疗服务能力。"
