    "content": "快科技10月4日消息，今日，“网红慧慧饱饱被封号”话题登上微博热搜。 据媒体报道， 近日，靠“微商女强人”抽象视频走红的百万网红“慧慧饱饱”账号被禁止关注，主页作品也被清空。 而她的另一个小号“慧慧饱饱朋友圈”，拥有粉丝58.2万，虽暂未被封但同样停止内容更新。 平台官方截至目前尚未就封号原因发布任何公告，有评论认为，平台对多次触碰底线的账号选择直接关停，释放了明确的整顿信号。 第三方数据显示，慧慧饱饱1-20s视频广告报价为7.6万，21-60s视频广告报价为8.2万，60s以上视频广告报价为9万。 她巅峰期曾年…"
