    "content": "10月2日，中国奥园（03883.HK）公告称，其接管人于9月29日订立临时协议，以现金作价1.5亿港元出售一处位于中国香港葵涌的12层高建筑物业，买方为大洋环球控股有限公司的间接全资附属公司。 中国奥园此前公告显示，富事高咨询（香港）有限公司的霍义禹及周伟成获委任为联合及个别接管人和管理人，接管相关资产。 根据此前公告内容的披露，该接管针对恒生银行作为受益人的按揭担保资产，该按揭为恒生银行向中国奥园间接全资附属公司提供的贷款，以中国奥园担保，并以附属公司持有的位于中国香港葵涌市地段第46号及地上12层建筑物作为抵…"
