    "content": "新华社塔什干10月4日电 通讯｜乌兹别克斯坦跳蚤市场里的“中文微课堂” 新华社记者包诺敏 10月的塔什干，城东郊的扬吉阿巴德跳蚤市场里熙熙攘攘。57岁的商户拉希德正用流利的中文向几位中国游客报价，手里不时比划着物品的尺寸。旁边的小女孩扎里娜凑上前来，仰着脸插了一句中文：“你好，好久不见！”引得游客们一阵惊喜。 很难想象，在这个陈列着苏联老式相机、发黄明信片与黑胶唱片的二手货品摊位前，竟藏着一处“中文微课堂”。 “以前看到中国游客，我一句中文都不会，只能干着急。”拉希德回忆道。他开始尝试用“笨办法”自学。每当有中国游…"
