    "content": "今年4月27日，中共上海市委办公厅、上海市人民政府办公厅印发《加快建设青年发展型城市的若干措施》（以下称为“《若干措施》”），从四个方面14项措施，部署上海加快推进青年发展型城市建设。文件于9月5日在上海市政府官网全文公布。 青年发展型城市并非一个新概念。2022年4月，中宣部、国家发改委、共青团中央等17部门联合印发《关于开展青年发展型城市建设试点的意见》，将这项工作上升为国家战略。 上海在此基础上实现制度跃升：2026年4月市委、市政府出台专项文件，同年5月市人大常委会表决通过《关于促进青年发展型城市建设的决定…"
