    "description": "IT之家 10 月 4 日消息，据 Rust 基金会，Rust 现已成为微软公司内部的“一级编程语言（Tier-1）”，与 C++、C#和 TypeScript 并列。 需要注意的是，这里的 Tier-1 是微软内部使用的分类，并非 Rust 项目自身的支持等级。对于微软内部开发团队而言，这意味着团队今后无需再自行搭建 Rust 相关的开发和生产环境。微软将提供从代码编写、构建、测试到发布和长期维护的一整套标准流程。此外，Rust 项目…",
    "content": "IT之家 10 月 4 日消息，据 Rust 基金会，Rust 现已成为微软公司内部的“一级编程语言（Tier-1）”，与 C++、C#和 TypeScript 并列。 需要注意的是，这里的 Tier-1 是微软内部使用的分类，并非 Rust 项目自身的支持等级。对于微软内部开发团队而言， 这意味着团队今后无需再自行搭建 Rust 相关的开发和生产环境。微软将提供从代码编写、构建、测试到发布和长期维护的一整套标准流程 。此外，Rust 项目还将纳入微软现有的软件安全、合规等开发流程。 事实上，微软工程师已经使用 R…"
