    "content": "【1】10月3日， @中国东方航空 再次发布情况通报 【2】香港也开始抓生育了，港府这11项生育政策力度如何？ 【3】人民日报：加快建设强大国内市场，扩大内需仍有巨大潜力、广阔空间。 【4】 #原来胖东来也不是双休# 胖东来之前只有管理层享受双休，一线普通员工一直是单休。 不过于东来已经官宣：2027年3月起，全员双休，每天只干7小时，每周35小时——工资一分不降 【5】上海一男子在女友生日当天发520元红包，没等来对方回1314元红包，报警称被骗；经调解后女生退还红包：再也不想和他见面 【6】国庆黄金周，热门景点…"
