    "content": "IT之家 10 月 4 日消息，中国人民大学今日宣布， 近期收到一位校友 5.03 亿元捐赠 ，用于支持母校通州校区体育中心建设。 官方并未公布捐赠者的相关信息。 据介绍，体育中心是中国人民大学通州校区重要标志性建筑之一，在设计时提取陕北公学时期标志性“窑洞”元素，彰显校园文化脉络，以玉兰花造型和元素贯穿其中，营造“一树玉兰”的雅致意境，以连续人字形曲线窗，凝炼“人民、人本、人文”的精神内核。 ▲ 西立面效果图 IT之家获悉，体育中心总建筑面积约 4.2 万平方米，集篮球、羽毛球、网球、乒乓球、游泳、攀岩、健身等各…"
