    "content": "新华社北京10月4日电 据美国《华尔街日报》3日报道，美国总统特朗普已任命国家情报总监杰伊·克莱顿为白宫人工智能事务主管。 报道说，克莱顿将领导“超级智能工作组”，在120天内提交一份有关人工智能风险和机遇的报告。根据特朗普9月29日签署的一项行政令，联邦行政部门和机构将把“人工智能”改称为“超级智能”。 这是9月19日在美国华盛顿拍摄的白宫。新华社记者白雪骐摄 克莱顿对《华尔街日报》说，成立工作组旨在保护公众利益，以及保持美国在人工智能领域的领先地位。工作组成员包括副总统万斯、国防部长赫格塞思、财政部长贝森特和白…"
