    "description": "10月4日，爱知·名古屋亚运会正式落下帷幕。 中国体育代表团获得169枚金牌、89枚银牌、83枚铜牌，共计341枚奖牌，位居金牌榜、奖牌榜首位，创境外参加亚运会最佳战绩。 奖牌之外，对中国体育代表团而言，这届赛事从一开始就被赋予了一个明确的定位——洛杉矶奥运会前的“中考”。815名运动员、38个大项、369个小项的参赛规模，本身就是一次对奥运备战体系的全景检验。 金牌榜上的领先并不令人意外，真正值得梳理的，是那些在“中考”中浮现出的信号…",
    "content": "10月4日，爱知·名古屋亚运会正式落下帷幕。 中国体育代表团获得169枚金牌、89枚银牌、83枚铜牌，共计341枚奖牌，位居金牌榜、奖牌榜首位，创境外参加亚运会最佳战绩。 奖牌之外，对中国体育代表团而言，这届赛事从一开始就被赋予了一个明确的定位——洛杉矶奥运会前的“中考”。815名运动员、38个大项、369个小项的参赛规模，本身就是一次对奥运备战体系的全景检验。 金牌榜上的领先并不令人意外，真正值得梳理的，是那些在“中考”中浮现出的信号：哪些新人已经具备了站上奥运舞台的底气，哪些项目又在看似繁荣的奖牌数背后，暴露出…"
