    "pub_date": "2026-10-04 14:33:52",
    "author": "侯文坤",
    "description": "新华社武汉10月4日电（记者侯文坤）“柳条得用‘三浸三蒸’的老法子处理，韧劲才够。编的时候，要按照‘三折两绕’的技法，才牢靠。”清晨，湖北省襄阳市襄州区程河镇赵坡村还浸在薄雾中，57岁的村民赵春玉已经坐在自家院子里忙碌起来。 只见柳枝在她满是厚茧的手指间翻飞，这边一穿，那边一绕，大约半个钟头，一只纹路细密的果篮便已显出轮廓。国庆假期，这样的场景在程河镇很多农户家都能见到——一根根柔韧的柳条，在村民手中上下穿梭，编出精致的器物，也织出当地…",
    "content": "新华社武汉10月4日电（记者侯文坤）“柳条得用‘三浸三蒸’的老法子处理，韧劲才够。编的时候，要按照‘三折两绕’的技法，才牢靠。”清晨，湖北省襄阳市襄州区程河镇赵坡村还浸在薄雾中，57岁的村民赵春玉已经坐在自家院子里忙碌起来。 只见柳枝在她满是厚茧的手指间翻飞，这边一穿，那边一绕，大约半个钟头，一只纹路细密的果篮便已显出轮廓。国庆假期，这样的场景在程河镇很多农户家都能见到——一根根柔韧的柳条，在村民手中上下穿梭，编出精致的器物，也织出当地村民稳稳当当的日子。 柳编技艺走进程河镇学生课堂。新华社发 “小时候就看着大人用…"
