    "author": "邹欣媛",
    "description": "新华社银川10月4日电（记者邹欣媛）国庆长假期间，人们探亲访友、聚餐出游活动增多。因饮食不当、作息紊乱引发的肝胆胰急症也进入高发期。医生提醒，假期暴饮暴食可能诱发多种急症，出现相关症状后务必及时就医。 “一到长假，由于人们连续进食高脂食物、过量饮酒，我们接诊的肝胆胰急症患者会明显增加。”宁夏医科大学总医院消化内科主任医师黄李雅说，除了常见的急性肠胃炎外，短时间内大量摄入高脂食物会让胆囊剧烈收缩，如果患者本身患有胆结石，结石很容易卡顿在胆…",
    "content": "新华社银川10月4日电（记者邹欣媛）国庆长假期间，人们探亲访友、聚餐出游活动增多。因饮食不当、作息紊乱引发的肝胆胰急症也进入高发期。医生提醒，假期暴饮暴食可能诱发多种急症，出现相关症状后务必及时就医。 “一到长假，由于人们连续进食高脂食物、过量饮酒，我们接诊的肝胆胰急症患者会明显增加。”宁夏医科大学总医院消化内科主任医师黄李雅说，除了常见的急性肠胃炎外，短时间内大量摄入高脂食物会让胆囊剧烈收缩，如果患者本身患有胆结石，结石很容易卡顿在胆囊管，从而诱发急性胆囊炎或胆绞痛。此类患者通常会出现右上腹突发持续性胀痛，或阵发…"
