    "description": "重庆綦江区石壕镇地处渝黔交界，是中央红军长征过境、转战地。此地地处遵义会议与四渡赤水的关键转角，红军曾在此扼守护卫遵义会议顺利召开，红一军团也曾在此驻扎、佯攻重庆，全镇至今留存50多处红军转战遗址，红色底蕴深厚。 曾经的石壕镇依托煤矿产业发展，2020年煤矿关停后，村庄发展陷入沉寂。当地深挖红色资源、传承长征精神，全面摸排修缮红军司令部旧址、红军桥、红军路等遗址，打造3公里红色研学参观环线，激活红色文旅经济。目前，石壕镇红色文旅热度持续…",
    "content": "重庆綦江区石壕镇地处渝黔交界，是中央红军长征过境、转战地。此地地处遵义会议与四渡赤水的关键转角，红军曾在此扼守护卫遵义会议顺利召开，红一军团也曾在此驻扎、佯攻重庆，全镇至今留存50多处红军转战遗址，红色底蕴深厚。 曾经的石壕镇依托煤矿产业发展，2020年煤矿关停后，村庄发展陷入沉寂。当地深挖红色资源、传承长征精神，全面摸排修缮红军司令部旧址、红军桥、红军路等遗址，打造3公里红色研学参观环线，激活红色文旅经济。目前，石壕镇红色文旅热度持续攀升，去年接待游客超12万人次，今年已承接216支研学团队、共计3.1万人次。 …"
