    "content": "西风烈，长空雁叫霜晨月。 娄山关，素有黔北咽喉之称，地势险要，堪称“一夫当关、万夫莫开”。1935年1月，中央红军挺进遵义，一克娄山关，确保了遵义会议的顺利召开。2月，红军在四渡赤水的转战途中，再克娄山关，赢得长征路上首场重大胜利。这场胜仗，极大提振鼓舞了红军士气，沉重打击了敌人的嚣张气焰。 红军攻克娄山关后，毛泽东挥毫写下《忆秦娥·娄山关》。这首词，落在了娄山关的千峰万仞之间，也化作如今校园中的书声琅琅。 今年是中国工农红军长征胜利90周年。娄山关的烽烟早已散尽，但“而今迈步从头越”的豪情，依然在每一代人心中回响…"
